        return string.match(Path, "([^/]+)%.lua$")
    end,

    --// Get the list of feature module names.
    GetFeatureNames = function(self)
        local Names = {}
        for Path in pairs(self.FEATURE_MODULES) do
            table.insert(Names, self:NameFromPath(Path))
        end
        table.sort(Names)
        return Names
    end,

